import { ref, onMounted } from 'vue';
import axios from 'axios';
import { Chart, registerables } from 'chart.js';
import AppLayout from './AppLayout.vue';
Chart.register(...registerables);
const API_URL = process.env.VUE_APP_API_URL || 'http://localhost:8000/api';
export default {
  name: 'AdvancedAnalytics',
  setup() {
    const activeTab = ref('trends');
    const plants = ref([]);

    // Trends
    const trendsPlant = ref('');
    const trendsDays = ref(30);
    const trendsData = ref(null);
    const trendsChart = ref(null);

    // Comparison
    const comparisonData = ref(null);

    // Predictions
    const predictionPlant = ref('');
    const predictionsData = ref(null);

    // Anomalies
    const anomaliesData = ref(null);

    // Efficiency
    const efficiencyPlant = ref('');
    const efficiencyData = ref(null);
    const tabs = [{
      id: 'trends',
      label: 'Trends',
      icon: 'pi pi-chart-line'
    }, {
      id: 'comparison',
      label: 'Comparison',
      icon: 'pi pi-chart-bar'
    }, {
      id: 'predictions',
      label: 'Predictions',
      icon: 'pi pi-forward'
    }, {
      id: 'anomalies',
      label: 'Anomalies',
      icon: 'pi pi-exclamation-triangle'
    }, {
      id: 'efficiency',
      label: 'Efficiency',
      icon: 'pi pi-gauge'
    }];
    const loadPlants = async () => {
      try {
        const response = await axios.get(`${API_URL}/plants/`);
        plants.value = response.data;
      } catch (error) {
        console.error('Failed to load plants:', error);
      }
    };
    const loadTrends = async () => {
      try {
        const params = {
          days: trendsDays.value
        };
        if (trendsPlant.value) params.plant_id = trendsPlant.value;
        const response = await axios.get(`${API_URL}/analytics/trends/`, {
          params
        });
        trendsData.value = response.data;
        renderTrendsChart();
      } catch (error) {
        console.error('Failed to load trends:', error);
      }
    };
    const loadComparison = async () => {
      try {
        const response = await axios.get(`${API_URL}/analytics/comparison/`);
        comparisonData.value = response.data;
      } catch (error) {
        console.error('Failed to load comparison:', error);
      }
    };
    const loadPredictions = async () => {
      if (!predictionPlant.value) return;
      try {
        const response = await axios.get(`${API_URL}/analytics/predictions/`, {
          params: {
            plant_id: predictionPlant.value
          }
        });
        predictionsData.value = response.data;
      } catch (error) {
        console.error('Failed to load predictions:', error);
      }
    };
    const loadAnomalies = async () => {
      try {
        const response = await axios.get(`${API_URL}/analytics/anomalies/`);
        anomaliesData.value = response.data;
      } catch (error) {
        console.error('Failed to load anomalies:', error);
      }
    };
    const loadEfficiency = async () => {
      try {
        const params = {};
        if (efficiencyPlant.value) params.plant_id = efficiencyPlant.value;
        const response = await axios.get(`${API_URL}/analytics/efficiency/`, {
          params
        });
        efficiencyData.value = response.data;
      } catch (error) {
        console.error('Failed to load efficiency:', error);
      }
    };
    let chartInstance = null;
    const renderTrendsChart = () => {
      if (!trendsData.value || !trendsChart.value) return;

      // Destroy existing chart if it exists
      if (chartInstance) {
        chartInstance.destroy();
      }
      const ctx = trendsChart.value.getContext('2d');

      // Prepare data from API response
      const labels = trendsData.value.daily_data.map(d => {
        const date = new Date(d.date);
        return date.toLocaleDateString('en-US', {
          month: 'short',
          day: 'numeric'
        });
      });
      const generationData = trendsData.value.daily_data.map(d => d.generation_mwh);
      const capacityFactorData = trendsData.value.daily_data.map(d => d.capacity_factor);
      chartInstance = new Chart(ctx, {
        type: 'line',
        data: {
          labels: labels,
          datasets: [{
            label: 'Generation (MWh)',
            data: generationData,
            borderColor: '#3b82f6',
            backgroundColor: 'rgba(59, 130, 246, 0.1)',
            borderWidth: 3,
            fill: true,
            tension: 0.4,
            yAxisID: 'y'
          }, {
            label: 'Capacity Factor (%)',
            data: capacityFactorData,
            borderColor: '#10b981',
            backgroundColor: 'rgba(16, 185, 129, 0.1)',
            borderWidth: 3,
            fill: true,
            tension: 0.4,
            yAxisID: 'y1'
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          interaction: {
            mode: 'index',
            intersect: false
          },
          plugins: {
            legend: {
              display: true,
              position: 'top',
              labels: {
                font: {
                  size: 14,
                  weight: '600'
                },
                padding: 20,
                usePointStyle: true
              }
            },
            tooltip: {
              backgroundColor: 'rgba(0, 0, 0, 0.8)',
              padding: 12,
              titleFont: {
                size: 14,
                weight: 'bold'
              },
              bodyFont: {
                size: 13
              },
              borderColor: '#e2e8f0',
              borderWidth: 1
            }
          },
          scales: {
            x: {
              grid: {
                display: false
              },
              ticks: {
                font: {
                  size: 12,
                  weight: '600'
                },
                color: '#64748b'
              }
            },
            y: {
              type: 'linear',
              display: true,
              position: 'left',
              title: {
                display: true,
                text: 'Generation (MWh)',
                font: {
                  size: 13,
                  weight: '700'
                },
                color: '#3b82f6'
              },
              grid: {
                color: '#f1f5f9'
              },
              ticks: {
                font: {
                  size: 12,
                  weight: '600'
                },
                color: '#64748b'
              }
            },
            y1: {
              type: 'linear',
              display: true,
              position: 'right',
              title: {
                display: true,
                text: 'Capacity Factor (%)',
                font: {
                  size: 13,
                  weight: '700'
                },
                color: '#10b981'
              },
              grid: {
                drawOnChartArea: false
              },
              ticks: {
                font: {
                  size: 12,
                  weight: '600'
                },
                color: '#64748b'
              }
            }
          }
        }
      });
    };
    const formatDate = dateStr => {
      return new Date(dateStr).toLocaleDateString();
    };
    const getScoreClass = score => {
      if (score >= 80) return 'excellent';
      if (score >= 60) return 'good';
      if (score >= 40) return 'fair';
      return 'poor';
    };
    onMounted(() => {
      loadPlants();
      loadTrends();
    });
    return {
      activeTab,
      tabs,
      plants,
      trendsPlant,
      trendsDays,
      trendsData,
      trendsChart,
      comparisonData,
      predictionPlant,
      predictionsData,
      anomaliesData,
      efficiencyPlant,
      efficiencyData,
      loadTrends,
      loadComparison,
      loadPredictions,
      loadAnomalies,
      loadEfficiency,
      formatDate,
      getScoreClass
    };
  },
  components: {
    AppLayout
  }
};
